    lb = np.array([-np.inf, -np.inf, -np.inf])
    ub = np.array([np.inf, np.inf, np.inf])

    print(qpSWIFT.solve_sparse_H_diag_batch(qp_data=[(H, g, lb, ub, csc_matrix(E), b, csc_matrix(A), lbA, ubA)],
                                            options=options))


